  return `本次已收下有效部分：已整理 ${processed} 个来源范围，${pending.length} 个已读取范围尚未整理。${pending.map(location).join("；")}${unread.length ? `另有 ${unread.length} 段后续${unread.every((r) => r.kind === "pdf") ? "页" : "材料"}尚未读取：${unread.map(location).join("；")}` : ""}`;
